// Gate bhejne ke baad: Data Table me kya store karna hai wo tay karo (store ya skip)
// Actual write next nodes me hota hai (Store Pending? -> Upsert Pending Row)
const ctx = $('Build Follow Gate1').item.json;

// Re-gate (user ne button dabaya par abhi follow nahi kiya): existing row ko mat chhedo (created_at / TTL reset nahi)
if (ctx.flow !== 'comment') {
  return { json: { store: false, note: 're-gate: existing pending row kept', igsid: ctx.igsid } };
}
// Test payload: fake data store mat karo
if (ctx.is_test) {
  return { json: { store: false, note: 'test payload - not stored' } };
}

// Private reply response me recipient_id aata hai. Wahi IGSID messaging webhook me sender.id hoga
const igsid = String($json.recipient_id || ctx.igsid);

return {
  json: {
    store: true,
    igsid,
    message: String(ctx.message ?? ''),     // original sheet message (follow ke baad yehi jaayega)
    keyword: String(ctx.keyword ?? ''),
    comment_id: String(ctx.comment_id ?? ''),
    media_id: String(ctx.media_id ?? ''),
    username: String(ctx.username ?? ''),
    created_at: new Date().toISOString(),
    ttl_minutes: 10                         // follow karne ka time ~2-3 min => 10 min kaafi
  }
};

// Messaging webhook se "I'm Following" tap nikalo (pending lookup ab Data Table node karta hai)
// Button template ka tap = postback event (ev.postback.payload). Purana quick_reply (ev.message.quick_reply.payload) bhi handle hota hai.
// Har skip case me item aata hai (valid:false + skip_reason) taaki output me reason dikhe
const body = $input.first().json.body || {};
const PAYLOAD = 'IM_FOLLOWING';

// FALLBACK: Instagram buttons sirf MOBILE APP me dikhte hain (instagram.com desktop par nahi).
// Isliye user "i am following" jaisa text type kare to bhi wahi maana jaata hai. Band karna ho to false karo.
const ACCEPT_TYPED_TEXT = true;
const TYPED_OK = ['i am following', 'im following', 'following', 'followed', 'i followed', 'i have followed', 'followed you', 'followed us', 'done'];
const normText = (s) => String(s ?? '').toLowerCase().replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();

// Duplicate protection (Meta retries): sirf message ids yaad rakhne ke liye static data (pending data isme nahi hai)
const sd = $getWorkflowStaticData('global');
sd.seenMsgs = sd.seenMsgs || {};
const now = Date.now();
for (const m of Object.keys(sd.seenMsgs)) {
  if (now - sd.seenMsgs[m] > 24 * 3600 * 1000) delete sd.seenMsgs[m];   // 24h
}

const out = [];
const skip = (reason, ev, entry) =>
  out.push({ json: { valid: false, skip_reason: reason, igsid: String(ev?.sender?.id ?? ''), entry_id: String(entry?.id ?? '') } });

for (const entry of (body.entry || [])) {
  for (const ev of (entry.messaging || [])) {
    const msg = ev.message;
    const pb = ev.postback;
    if (!msg && !pb) { skip('not a message/postback event (read/etc)', ev, entry); continue; }
    // Apne bheje messages ke echo ignore
    if (msg?.is_echo || String(ev.sender?.id) === String(entry.id)) { skip('echo / own account message', ev, entry); continue; }

    // Button tap (postback) / quick_reply payload, ya fallback me typed text
    const isTyped = ACCEPT_TYPED_TEXT && !pb && !msg?.quick_reply && TYPED_OK.includes(normText(msg?.text));
    const payload = pb?.payload ?? msg?.quick_reply?.payload ?? (isTyped ? PAYLOAD : undefined);
    if (payload !== PAYLOAD) { skip('not an ' + PAYLOAD + ' tap / typed confirmation', ev, entry); continue; }

    // Duplicate protection
    const mid = String(pb?.mid || msg?.mid || '');
    if (mid && sd.seenMsgs[mid]) { skip('duplicate event', ev, entry); continue; }
    if (mid) sd.seenMsgs[mid] = now;

    out.push({ json: { valid: true, igsid: String(ev.sender.id), entry_id: String(entry.id), mid, via: pb ? 'postback' : (isTyped ? 'typed_text' : 'quick_reply') } });
  }
}

if (!out.length) out.push({ json: { valid: false, skip_reason: 'no messaging events in payload' } });
return out;

// DM fail hone par readable error + hint
const e = $input.first().json;
const raw = JSON.stringify(e);
const sub = (raw.match(/error_subcode\W{1,6}(\d+)/) || [])[1] || null;
const code = (raw.match(/(?:^|[^a-z_])code\W{1,6}(\d+)/i) || [])[1] || null;

const subHints = {
  '2534025': 'Comment private reply ke liye invalid: fake/test comment_id, is comment pe pehle hi private reply ja chuki, apne hi account ka comment, 7 din se purana, ya reply-type (non top-level) comment.'
};
const codeHints = {
  '190': 'Access token expire/invalid hai. IG_Accounts me is account ka token check karo (Token Refresh workflow ka output dekho).',
  '10': 'Permission missing: instagram_manage_messages (Advanced Access / App Review + app Live mode) check karo.',
  '200': 'Permission missing: instagram_manage_messages check karo.',
  '100': 'Invalid parameter: comment_id ya message check karo.',
  '613': 'Rate limit lag gayi, thodi der baad try karo.',
  '4': 'App rate limit lag gayi, thodi der baad try karo.'
};

let ctx = {};
try {
  const mk = $('Match Keyword').first().json;
  ctx = { ig_account_id: mk.ig_account_id, comment_id: mk.comment_id, username: mk.username, keyword: mk.keyword };
} catch (err) {}

return [{
  json: {
    dm_failed: true,
    ...ctx,
    error_code: code,
    error_subcode: sub,
    hint: subHints[sub] || codeHints[code] || 'Error field dekh',
    error: e.error || e
  }
}];

// ============================================================
// Extract Instagram Comment
// Har webhook event ko normalize karta hai. Skip hone par bhi item aata hai (valid:false + skip_reason)
// ============================================================
const ALLOW_SELF_COMMENTS = false; // TESTING: apne hi IG account ke TOP-LEVEL comment se test karna ho to true karo, production me false

const body = $input.first().json.body || {};

// Meta dashboard "Test" button ke payload me entry[] nahi hota ya entry.id = 0 hoti hai (fake comment_id) -> is_test flag lagta hai
const isTest =
  !(Array.isArray(body.entry) && body.entry.length) ||
  body.entry.every((e) => !e.id || String(e.id) === '0');

// Duplicate protection: 24 ghante tak seen comment_ids yaad rakho
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const now = Date.now();
for (const id of Object.keys(sd.seen)) {
  if (now - sd.seen[id] > 24 * 3600 * 1000) delete sd.seen[id];
}

let entries = Array.isArray(body.entry) && body.entry.length ? body.entry : null;
if (!entries) {
  entries = body.value ? [{ id: '', changes: [{ field: body.field || 'comments', value: body.value }] }] : [];
}

const out = [];
const skip = (reason, v, entry) =>
  out.push({
    json: {
      valid: false,
      skip_reason: reason,
      comment_id: String(v?.id ?? ''),
      comment_original: v?.text ?? '',
      from_id: String(v?.from?.id ?? ''),
      entry_id: String(entry?.id ?? ''),
      parent_id: String(v?.parent_id ?? '')
    }
  });

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const v = change.value;
    if (change.field && change.field !== 'comments') { skip('field is "' + change.field + '", not comments', v, entry); continue; }
    if (!v || !v.id) { skip('no comment id in payload', v, entry); continue; }
    if (typeof v.text !== 'string' || !v.text.trim()) { skip('comment has no text', v, entry); continue; }

    // --- Own-account detection ---
    // entry.id = hamara IG account id. from.id ya from.self_ig_scoped_id uske barabar ho => comment hamare account ka hai
    const entryId = String(entry?.id ?? '');
    const hasRealEntry = entryId !== '' && entryId !== '0';
    const fromId = String(v.from?.id ?? '');
    const selfScopedId = String(v.from?.self_ig_scoped_id ?? '');
    const isOwnAccount = hasRealEntry && (fromId === entryId || selfScopedId === entryId);

    // 1) Hamare apne public replies (workflow khud bhejta hai): parent_id + self id => hamesha skip (ALLOW_SELF_COMMENTS se bhi nahi khulta)
    if (v.parent_id && (isOwnAccount || selfScopedId !== '')) {
      skip('own account reply (parent_id + self_ig_scoped_id / from.id === entry.id) - loop protection', v, entry);
      continue;
    }
    // 2) Kisi bhi comment ka reply (non top-level) => skip (test payload ko chhodkar)
    if (v.parent_id && !isTest) { skip('it is a reply to a comment (parent_id present)', v, entry); continue; }
    // 3) Apne account ka top-level comment => skip (testing ke liye ALLOW_SELF_COMMENTS = true)
    if (!ALLOW_SELF_COMMENTS && isOwnAccount) {
      skip('comment is from your own account (entry.id == from.id). Testing ke liye ALLOW_SELF_COMMENTS = true karo', v, entry);
      continue;
    }

    // --- Duplicate protection ---
    const cid = String(v.id);
    if (!isTest && sd.seen[cid]) { skip('duplicate event (already processed)', v, entry); continue; }
    if (!isTest) sd.seen[cid] = now;

    out.push({
      json: {
        valid: true,
        is_test: isTest,
        comment_id: cid,
        comment_original: v.text,
        username: v.from?.username || '',
        instagram_user_id: v.from?.id || '',
        media_id: String(v.media?.id || ''),
        entry_id: entryId,                 // webhook entry.id = IG_Accounts.ig_account_id
        timestamp: new Date().toISOString()
      }
    });
  }
}

if (!out.length) {
  out.push({ json: { valid: false, skip_reason: 'payload me koi comment change nahi mila', raw_body: JSON.stringify(body).slice(0, 1500) } });
}
return out;

// ============================================================
// Match Keyword  (run once for all items)
// Input: Keywords Data Table rows (is ig_account_id ke)
// Columns: ig_account_id | username | keyword | message | comment_reply1-3 | media_id | require_follow | is_active
// Rule: EXACT match only. Case-insensitive (DM = Dm = dm). Extra text/symbols/emoji => no match.
// ============================================================

// Normalize: invisible chars hatao, NBSP -> space, spaces collapse + trim, UPPERCASE.
// Punctuation / emoji / extra words ko NAHI hatata (isliye "*DM*" ya "dm please" match nahi hoga)
const norm = (s) =>
  String(s ?? '')
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();

// media_id clean: spaces, zero-width chars aur leading apostrophe hata do. Blank => '' (matlab saare posts)
const cleanId = (s) =>
  String(s ?? '').replace(/[\u200B-\u200D\uFEFF]/g, '').trim().replace(/^'+/, '').trim();

// Boolean ya string dono chalenge: true/'true'/1/yes/y => true. Baaki sab (blank bhi) => false
const toBool = (v) => v === true || ['true', '1', 'yes', 'y'].includes(String(v ?? '').trim().toLowerCase());

const allRows = $input.all().map((r) => r.json).filter((r) => r && r.keyword !== undefined && r.keyword !== null);
const ctxItems = $('Resolve Account').all().filter((i) => i.json.account_ok === true);

const results = [];
for (const item of ctxItems) {
  const c = item.json;

  // ---------- 1) Is account ke active rules ----------
  const rules = [];
  for (const row of allRows) {
    if (String(row.ig_account_id ?? '').trim() !== c.ig_account_id) continue;   // safety: sirf isi account ke rules
    if (!toBool(row.is_active)) continue;
    const keyword = norm(row.keyword);
    if (!keyword) continue;

    // comment_reply1/2/3 (ya comment_reply_2, Comment Reply 2 jaise naam) - sirf non-empty
    const replyKeys = Object.keys(row)
      .filter((k) => /^comment[\s_]?reply[\s_]?\d*$/i.test(k))
      .sort();

    rules.push({
      keyword,
      message: String(row.message ?? ''),
      comment_replies: replyKeys.map((k) => String(row[k] ?? '').trim()).filter(Boolean),
      reply_columns_found: replyKeys,             // debug: kaun se reply columns mile
      media_id: cleanId(row.media_id),            // filled => sirf us post/reel pe, blank => saare posts
      require_follow: toBool(row.require_follow)  // true => follow-gate
    });
  }
  // Post-specific rule global (all posts) rule se pehle
  rules.sort((a, b) => (b.media_id ? 1 : 0) - (a.media_id ? 1 : 0));

  // ---------- 2) Comment ko EXACT match karo ----------
  const commentNorm = norm(c.comment_original);
  const commentMedia = cleanId(c.media_id);
  const rule = rules.find((r) => commentNorm === r.keyword && (!r.media_id || r.media_id === commentMedia));

  if (!rule) {
    results.push({ json: { ...c, matched: false, skip_reason: 'no exact keyword match', comment_normalized: commentNorm, keywords_loaded: rules.length } });
  } else if (!rule.message) {
    results.push({ json: { ...c, matched: false, skip_reason: 'keyword matched but message empty in Keywords table', keyword: rule.keyword } });
  } else {
    results.push({
      json: {
        ...c,
        matched: true,
        keyword: rule.keyword,
        rule_media_id: rule.media_id,
        message: rule.message,
        comment_replies: rule.comment_replies,
        reply_count: rule.comment_replies.length,          // debug: kitne replies mile (1/2/3)
        reply_columns_found: rule.reply_columns_found,     // debug: kaun se columns padhe gaye
        require_follow: rule.require_follow
      }
    });
  }
}
if (!results.length) results.push({ json: { matched: false, skip_reason: 'no active account context' } });
return results;

// Matched comment ke liye PUBLIC reply text decide karo (hamesha bhejna hai)
// Priority: Keywords table ke comment_reply1/2/3 me se random ek (sirf non-empty) -> sab khali ho to neeche ke default variants
const variants = [
  'Check your DM 📩',
  'Just sent you a DM 📩',
  'Done! Check your inbox 📩',
  'Sent! Have a look at your DMs 📩'
];
const pool = Array.isArray($json.comment_replies)
  ? $json.comment_replies.map((s) => String(s ?? '').trim()).filter(Boolean)
  : [];
const list = pool.length ? pool : variants;
const reply = list[Math.floor(Math.random() * list.length)];

// Poora Match item aage pass hota hai (access_token + account info bhi, baad ke HTTP nodes ko chahiye)
return { json: { ...$json, reply_text: reply } };

// Comment reply fail hone par readable error + hint
const e = $input.first().json;
const raw = JSON.stringify(e);
const sub = (raw.match(/error_subcode\W{1,6}(\d+)/) || [])[1] || null;
const code = (raw.match(/(?:^|[^a-z_])code\W{1,6}(\d+)/i) || [])[1] || null;

const codeHints = {
  '190': 'Access token expire/invalid hai. IG_Accounts me is account ka token check karo (Token Refresh workflow ka output dekho).',
  '10': 'Permission missing: instagram_manage_comments (Advanced Access / App Review + app Live mode) check karo.',
  '200': 'Permission missing: instagram_manage_comments check karo.',
  '100': 'Invalid parameter: comment delete ho gaya ho, ya comment_id / message galat ho sakta hai.',
  '613': 'Rate limit lag gayi, thodi der baad try karo.',
  '4': 'App rate limit lag gayi, thodi der baad try karo.'
};

let ctx = {};
try {
  const b = $('Build Comment Reply1').first().json;
  ctx = { comment_id: b.comment_id, username: b.username, reply_text: b.reply_text };
} catch (err) {}

// NOTE: public reply fail hone par flow rukta nahi - DM / follow-gate phir bhi chalta hai
return [{
  json: {
    comment_reply_failed: true,
    ...ctx,
    error_code: code,
    error_subcode: sub,
    hint: codeHints[code] || 'Error field dekh',
    error: e.error || e
  }
}];

// Public reply ke baad clean DM context wapas banao (HTTP node ka response context mita deta hai)
// Public reply fail ho ya success - dono case me flow yahin aata hai
const ctx = $('Build Comment Reply1').item.json;

return {
  json: {
    ...ctx,
    igsid: String(ctx.instagram_user_id || ''),   // commenter ka IGSID (comment webhook ka from.id)
    public_reply_sent: !$json.error,
    public_reply_id: $json.id || null
  }
};

// Follow Status API ka result -> clean boolean. Success aur error dono outputs yahin aate hain.
// Spec: "Follows" => normal DM. "Not following / check fail / error" => follow-gate.
const ctx = $('Restore DM Context1').item.json;

const following = $json.is_user_follow_business === true;   // sirf explicit true hi "follows" maana jaata hai
const errMsg = $json.error
  ? String($json.error.message || JSON.stringify($json.error)).slice(0, 300)
  : null;

return {
  json: {
    ...ctx,
    flow: 'comment',               // gate DM private reply (comment_id) se jaayega
    is_following: following,
    follow_check_error: errMsg     // null => API ne clean answer diya
  }
};

// Follow-gate message banata hai: BUTTON TEMPLATE (inline buttons, same bubble me).
// Quick Reply chips Instagram ke "Message Requests" folder me render nahi hote (non-followers ke DMs wahin jaate hain),
// isliye "I'm Following" ko postback button banaya hai - wo requests folder me bhi dikhta hai.
// Dono flows yahin se guzarte hain: comment flow (private reply) aur recheck flow (IGSID se).
const GATE_USERNAME = String($json.account_username || '').replace(/^@/, '').trim();   // IG_Accounts.username
if (!GATE_USERNAME) throw new Error('IG_Accounts.username missing - follow gate link nahi ban sakta');
const PROFILE_URL = 'https://instagram.com/' + GATE_USERNAME;

const text =
  'You are not following us yet ❤️\n\n' +
  'Please follow us first:\n' +
  PROFILE_URL + '\n\n' +
  'Once you follow, tap the button below 👇';            // button template text limit: 640 chars

// Private Reply (comment_id) SIRF pehle gate message ke liye. Re-gate (button dabane ke baad) IGSID se jaata hai.
const recipient = $json.flow === 'comment'
  ? { comment_id: $json.comment_id }
  : { id: $json.igsid };

const body = {
  recipient,
  message: {
    attachment: {
      type: 'template',
      payload: {
        template_type: 'button',
        text,
        buttons: [                                        // max 3 buttons, title max 20 chars
          { type: 'web_url', url: PROFILE_URL, title: 'Visit Profile' },
          { type: 'postback', title: "I'm Following", payload: 'IM_FOLLOWING' }
        ]
      }
    }
  }
};

return { json: { ...$json, gate_body: JSON.stringify(body) } };

// Re-check follow result -> clean boolean (success + error dono outputs yahin aate hain)
const ctx = $('Evaluate Pending (TTL)').item.json;

const following = $json.is_user_follow_business === true;
const errMsg = $json.error
  ? String($json.error.message || JSON.stringify($json.error)).slice(0, 300)
  : null;

return {
  json: {
    ...ctx,
    flow: 'recheck',               // re-gate IGSID se jaayega (comment_id dubara use nahi ho sakta)
    is_following: following,
    follow_check_error: errMsg
  }
};

// Data Table "Get Pending Row" ke result + TTL check  (run once for all items)
// Get node alwaysOutputData hai: row na mile to khali item aata hai (igsid field nahi hoti)
const DEFAULT_TTL_MINUTES = 10;
const now = Date.now();

// Data Table se aayi rows -> igsid se map
const rows = {};
for (const r of $input.all()) {
  if (r.json && r.json.igsid) rows[String(r.json.igsid)] = r.json;
}

const out = [];
// Resolve Tap Account: entry_id se mila account (token + username) - sirf valid account wale taps
for (const item of $('Resolve Tap Account').all().filter((i) => i.json.account_ok === true)) {
  const { igsid, mid, entry_id, via, ig_account_id, account_username, access_token } = item.json;
  const row = rows[igsid];
  const acc = { ig_account_id, account_username, access_token };

  // 1) row nahi mili -> ignore
  if (!row) {
    out.push({ json: { found: false, expired: false, igsid, skip_reason: 'no pending row for this IGSID - ignored' } });
    continue;
  }

  // 2) TTL check: age >= ttl_minutes => expired (next nodes row delete karenge)
  const ttlMs = (Number(row.ttl_minutes) || DEFAULT_TTL_MINUTES) * 60 * 1000;
  const created = Date.parse(row.created_at);
  if (!created || now - created >= ttlMs) {
    out.push({ json: { found: false, expired: true, igsid, skip_reason: 'pending row expired - will be deleted' } });
    continue;
  }

  // 3) mili aur valid: saari fields + account (token) aage pass
  out.push({
    json: {
      found: true, expired: false,
      igsid, mid, entry_id, via,
      ...acc,
      message: row.message, keyword: row.keyword, comment_id: row.comment_id,
      media_id: row.media_id, username: row.username,
      created_at: row.created_at, ttl_minutes: row.ttl_minutes
    }
  });
}

if (!out.length) out.push({ json: { found: false, expired: false, skip_reason: 'no valid tap to look up' } });
return out;

const toBool = (v) => v === true || ['true', '1', 'yes', 'y'].includes(String(v ?? '').trim().toLowerCase());
// IG_Accounts rows -> ig_account_id se map
const rows = {};
for (const r of $input.all()) {
  if (r.json && r.json.ig_account_id) rows[String(r.json.ig_account_id).trim()] = r.json;
}
const attach = (c) => {
  const acc = rows[String(c.entry_id || '').trim()];
  if (!acc) return { ...c, account_ok: false, skip_reason: 'IG_Accounts me entry.id ' + (c.entry_id || '(blank / test payload)') + ' nahi mila - skipped' };
  if (!toBool(acc.is_active)) return { ...c, account_ok: false, skip_reason: 'account inactive (is_active = false) - skipped' };
  const token = String(acc.access_token ?? '').trim();
  if (!token) return { ...c, account_ok: false, skip_reason: 'IG_Accounts.access_token khali hai - skipped' };
  return {
    ...c,
    account_ok: true,
    ig_account_id: String(acc.ig_account_id).trim(),
    account_username: String(acc.username ?? '').replace(/^@/, '').trim(),
    access_token: token
  };
};

const out = $('Extract Instagram Comment').all().filter((i) => i.json.valid).map((i) => ({ json: attach(i.json) }));
if (!out.length) out.push({ json: { account_ok: false, skip_reason: 'no valid comment to resolve' } });
return out;

const toBool = (v) => v === true || ['true', '1', 'yes', 'y'].includes(String(v ?? '').trim().toLowerCase());
// IG_Accounts rows -> ig_account_id se map
const rows = {};
for (const r of $input.all()) {
  if (r.json && r.json.ig_account_id) rows[String(r.json.ig_account_id).trim()] = r.json;
}
const attach = (c) => {
  const acc = rows[String(c.entry_id || '').trim()];
  if (!acc) return { ...c, account_ok: false, skip_reason: 'IG_Accounts me entry.id ' + (c.entry_id || '(blank / test payload)') + ' nahi mila - skipped' };
  if (!toBool(acc.is_active)) return { ...c, account_ok: false, skip_reason: 'account inactive (is_active = false) - skipped' };
  const token = String(acc.access_token ?? '').trim();
  if (!token) return { ...c, account_ok: false, skip_reason: 'IG_Accounts.access_token khali hai - skipped' };
  return {
    ...c,
    account_ok: true,
    ig_account_id: String(acc.ig_account_id).trim(),
    account_username: String(acc.username ?? '').replace(/^@/, '').trim(),
    access_token: token
  };
};

const out = $('Extract Quick Reply').all().filter((i) => i.json.valid).map((i) => ({ json: attach(i.json) }));
if (!out.length) out.push({ json: { account_ok: false, skip_reason: 'no valid tap to resolve' } });
return out;
